"""Bundled synthetic demonstration cases (generated by ``scripts/build_detect_cases.py``)."""

from __future__ import annotations

from importlib.resources import files
from pathlib import Path
from typing import Any

from ..core.errors import Reason, Rejected
from ..core.safe_load import load_yaml
from .workflow import Inputs

CASES_DIR = Path(str(files("kestrix.detect") / "cases"))


def list_cases() -> list[dict[str, Any]]:
    return [manifest(p.name) for p in sorted(CASES_DIR.iterdir()) if (p / "case.yml").is_file()]


def manifest(case_id: str) -> dict[str, Any]:
    path = _case_dir(case_id) / "case.yml"
    doc = load_yaml(path.read_text())
    if not isinstance(doc, dict):
        raise Rejected(Reason.INVALID_INPUT, f"{case_id}: malformed manifest")
    return doc


def _case_dir(case_id: str) -> Path:
    path = (CASES_DIR / case_id).resolve()
    if not path.is_relative_to(CASES_DIR.resolve()) or not (path / "case.yml").is_file():
        raise Rejected(Reason.INVALID_INPUT, f"unknown case {case_id!r}")
    return path


def inputs(case_id: str) -> Inputs:
    d = _case_dir(case_id)

    def optional(name: str) -> str | None:
        return (d / name).read_text() if (d / name).is_file() else None

    return Inputs(
        rule_text=(d / "rule.yml").read_text(),
        mapping_text=(d / "mapping.yml").read_text(),
        dev_path=d / "development.jsonl",
        validation_path=d / "validation.jsonl",
        healthy_rule_text=optional("healthy_rule.yml"),
        healthy_mapping_text=optional("healthy_mapping.yml"),
    )
